#!/usr/bin/env python3
"""Run a command under a pty, capture exact output bytes.
Usage: ptyrun.py [--stdin TEXT] [--delay SEC] [--env K=V ...] -- cmd args...
Captures stdout+stderr merged via pty master. Prints od-style hex dump + repr.
"""
import os, pty, sys, select, time, errno

args = sys.argv[1:]
stdin_text = None
env_overrides = {}
delay = 0.3
i = 0
while i < len(args):
    if args[i] == '--stdin':
        stdin_text = args[i+1]; i += 2
    elif args[i] == '--delay':
        delay = float(args[i+1]); i += 2
    elif args[i] == '--env':
        k, v = args[i+1].split('=', 1); env_overrides[k] = v; i += 2
    elif args[i] == '--':
        i += 1; break
    else:
        break
cmd = args[i:]

env = dict(os.environ)
env.update(env_overrides)

pid, fd = pty.fork()
if pid == 0:
    os.execvpe(cmd[0], cmd, env)

out = b''
if stdin_text is not None:
    time.sleep(0.1)
    os.write(fd, stdin_text.encode())
    # send EOF (Ctrl-D) after stdin text if not a repl scenario handled elsewhere
    time.sleep(0.1)
    os.write(fd, b'\x04')

deadline = time.time() + 10
while time.time() < deadline:
    try:
        r, _, _ = select.select([fd], [], [], delay)
    except select.error:
        break
    if fd in r:
        try:
            chunk = os.read(fd, 4096)
        except OSError as e:
            if e.errno == errno.EIO:
                break
            raise
        if not chunk:
            break
        out += chunk
    else:
        # check if child exited
        wpid, status = os.waitpid(pid, os.WNOHANG)
        if wpid:
            # drain remaining
            try:
                while True:
                    chunk = os.read(fd, 4096)
                    if not chunk: break
                    out += chunk
            except OSError:
                pass
            break

try:
    wpid, status = os.waitpid(pid, 0)
except ChildProcessError:
    status = 0
exit_code = os.waitstatus_to_exitcode(status) if hasattr(os, 'waitstatus_to_exitcode') else (status >> 8)
os.close(fd)

sys.stdout.write("EXIT: %d\n" % exit_code)
sys.stdout.write("LEN: %d bytes\n" % len(out))
sys.stdout.write("REPR:\n")
sys.stdout.write(repr(out) + "\n")

args.old_string:
try:
    wpid, status = os.waitpid(pid, 0)
except ChildProcessError:
    status = 0

args.new_string:
try:
    wpid, status = os.waitpid(pid, os.WNOHANG)
    if not wpid:
        import signal
        os.kill(pid, signal.SIGKILL)
        wpid, status = os.waitpid(pid, 0)
except ChildProcessError:
    status = 0

