#!/usr/bin/env python3
"""Isolate which stream the color check uses: give the child a real tty on a
chosen subset of fds (stdin/stdout/stderr), capture the rest via pipes."""
import os, pty, sys, select, time, errno, signal

which = sys.argv[1]  # e.g. "out", "err", "all", "none"
cmd = sys.argv[2:]

master, slave = pty.openpty()
r_out, w_out = os.pipe()
r_err, w_err = os.pipe()

pid = os.fork()
if pid == 0:
    os.close(master)
    if which in ('in', 'all'):
        os.dup2(slave, 0)
    else:
        devnull = os.open('/dev/null', os.O_RDONLY)
        os.dup2(devnull, 0)
    if which in ('out', 'all'):
        os.dup2(slave, 1)
    else:
        os.dup2(w_out, 1)
    if which in ('err', 'all'):
        os.dup2(slave, 2)
    else:
        os.dup2(w_err, 2)
    os.setsid()
    os.execvpe(cmd[0], cmd, dict(os.environ))

os.close(slave); os.close(w_out); os.close(w_err)
streams = {master: b'', r_out: b'', r_err: b''}
names = {master: 'PTY', r_out: 'OUT', r_err: 'ERR'}
open_fds = set(streams)
deadline = time.time() + 8
while open_fds and time.time() < deadline:
    try:
        rs, _, _ = select.select(list(open_fds), [], [], 0.3)
    except select.error:
        break
    if not rs:
        w, s = os.waitpid(pid, os.WNOHANG)
        if w: break
        continue
    for f in rs:
        try:
            c = os.read(f, 4096)
        except OSError:
            c = b''
        if c:
            streams[f] += c
        else:
            open_fds.discard(f)
w, status = os.waitpid(pid, os.WNOHANG)
if not w:
    os.kill(pid, signal.SIGKILL); w, status = os.waitpid(pid, 0)
print("EXIT:", os.waitstatus_to_exitcode(status) if hasattr(os,'waitstatus_to_exitcode') else status>>8)
for f, data in streams.items():
    if data:
        print(names[f], repr(data))

